/** Returns a native Arabic action label for audit log entries when `locale === 'ar'`. */
export function localizeAuditAction(action: string, locale: Locale): string {
  if (locale !== 'ar') return action;
  return AUDIT_LABELS_AR[action] ?? action;
}
